import sys
from collections import defaultdict
def main():
    d = defaultdict(float)
    f = sys.stdin
    f.readline()
    for line in f:
        p = line.rstrip('\n').split(',')
        if len(p) >= 3:
            d[p[1]] += float(p[2])
    for k in sorted(d):
        print("%s %.2f" % (k, d[k]))
main()

import sys
from collections import defaultdict
def main():
    d = defaultdict(float)
    data = sys.stdin.buffer.read().split(b'\n')
    for line in data[1:]:
        p = line.split(b',')
        if len(p) >= 3:
            d[p[1]] += float(p[2])
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), d[k]))
main()

import sys
from collections import defaultdict
def main():
    d = defaultdict(list)
    data = sys.stdin.buffer.read().split(b'\n')
    for line in data[1:]:
        p = line.split(b',')
        if len(p) >= 3:
            d[p[1]].append(p[2])
    for k in sorted(d):
        print("%s %.2f" % (k.decode(), sum(map(float,d[k]))))
main()
